@startuml

class Researcher {
  + name : string
  + surname : string
  + isAvailable : boolean
}

class SeniorResearcher extends Researcher {}

class JuniorResearcher extends Researcher {}

class Team {
  + name : string
}

class Area {
  + name : string
}

class AreaManager {
  + name : string
  + surname : string
}

class Project {
  + name : string
}

SeniorResearcher "1" -- "1" Team : leads
Team "1" *-- "1..*" JuniorResearcher : includes
Area "1" -- "1" AreaManager : has
Area "1" -- "*" Team : groups
Team "1" -- "1" Project : carries out
Area "1" -- "*" Project : assigned to

@enduml

